import{_ as a,o as t,a as r,b as o}from"./app.C41L12d5.js";const i="/ascendc.github.io/assets/comm_reexec.CZ5qdVpu.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"融合算子编程","link":"/guide/operator_practice/simd_operator_impl/fusion_operator_programming/fusion_operator_programming"},{"text":"通算融合","link":"/guide/operator_practice/simd_operator_impl/fusion_operator_programming/general_fusion/basics"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/fusion_operator_programming/general_fusion/feature_scenarios"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/fusion_operator_programming/general_fusion/feature_scenarios.md","filePath":"guide/operator_practice/simd_operator_impl/fusion_operator_programming/general_fusion/feature_scenarios.md","outlineHeaders":[{"level":2,"title":"重执行","slug":"重执行","link":"#重执行"}],"lastUpdated":1787021884000}'),p={name:"guide/operator_practice/simd_operator_impl/fusion_operator_programming/general_fusion/feature_scenarios.md"};function s(_,e,n,c,d,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<div><article class="markdown-body"><h1>特性场景<span id="ZH-CN_TOPIC_0000002500548108"></span></h1><h2 id="重执行">重执行<span id="zh-cn_topic_0000002400328453_section11795221469"></span><a class="header-anchor" href="#重执行">​</a></h2><p>为避免执行通信任务的环境中硬件闪断导致发生通信中断，通算融合算子可通过配置编译宏与环境变量，开启重执行能力。通算融合算子开启重执行后，AI CPU在检测到环境异常时，通过下图示意的机制，通知AI Core重新下发通信任务，避免由于硬件闪断造成的通信中断，提升通信稳定性。</p><p>当前，该能力的支持情况如下：</p><div data-filter="950"><p>Ascend 950PR/Ascend 950DT不支持通算融合算子的重执行。</p></div><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品支持通算融合算子的重执行。</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品不支持通算融合算子的重执行。</p></div><p><strong>图1</strong> 通信任务重执行机制<span id="zh-cn_topic_0000002400328453_fig774612491699"></span><br><img src="'+i+`" alt title="通信任务重执行机制"></p><p>开启重执行的条件如下：</p><ul><li><p>通算融合算子的输出内存地址和输入内存地址不相同。</p></li><li><p>通算融合算子仅存在Server间通信（Server为计算节点，通常是8卡或16卡的昇腾NPU设备组成的服务器形态的统称）。</p></li><li><p>算子编译时，配置编译宏AICORE_EXCEPTION_RESTART，如下所示。具体的编译宏配置阶段和方式请参考<a href="../../../../programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process.html#custom-compile-options">支持自定义编译选项</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>add_ops_compile_options(ALL OPTIONS -DAICORE_EXCEPTION_RESTART)
</code></pre></div></li><li><p>配置HCCL重执行环境变量HCCL_OP_RETRY_ENABLE，开启重执行的检测和上报能力，该环境变量的说明请参考<a href="https://gitcode.com/cann/hccl/blob/master/docs/zh/user_guide/hccl_env/HCCL_OP_RETRY_ENABLE.md">HCCL_OP_RETRY_ENABLE</a>。请在算子执行前设置该环境变量，具体配置如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code># server间L1需配置为1,不支持跨超节点，L2配置为0。
export HCCL_OP_RETRY_ENABLE=&quot;L1:1, L2:0&quot;
</code></pre></div><p>注意，开启重执行后，若AI Core第一次下发通信任务后通信中断，默认只重执行一次。若需修改重执行次数或重传间隔时间，请参考<a href="https://gitcode.com/cann/hccl/blob/master/docs/zh/user_guide/hccl_env/HCCL_OP_RETRY_PARAMS.md">HCCL_OP_RETRY_PARAMS</a>。</p></li></ul></article></div>`,1)])])}const g=a(p,[["render",s]]);export{h as __pageData,g as default};
